// Mod 4: DRAW. A strip above the prompt that shows how full Claude's memory is.
import { advice, bar } from './bar.js'

export function register(on) {
  // Draw in the band above the prompt
  on('ui.render', { component: 'AbovePrompt' }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    // Ask Claude Code how much of the context window this session has used
    const usage = await $.session.usage()
    const percent = Math.round(usage.context.percent)
    return Box({
      flexDirection: 'row',
      children: [
        Text({ key: 'bar', children: ['memory ' + bar(percent) + ' ' + percent + '%'] }),
        Text({ key: 'advice', children: ['  ' + advice(percent)] }),
      ],
    })
  })

  // After every turn the number has changed, so ask for a redraw
  on('turn.complete', async ($, e, next) => {
    $.ui.invalidate('ui.render')
    return next(e)
  })
}

files.hooks/bar.js:
// Draw a number from 0 to 100 as ten blocks: 40 -> ████░░░░░░
export function bar(percent) {
  const full = Math.max(0, Math.min(10, Math.round(percent / 10)))
  return '█'.repeat(full) + '░'.repeat(10 - full)
}

// The words after the bar
export function advice(percent) {
  if (percent >= 80) return 'almost full: start a fresh session soon'
  if (percent >= 50) return 'half used'
  return 'plenty of room'
}

